mapper.select:
select count(*) from doctor_schedule


        and doctor_id in (select doctor_id from doctor_exp where real_name like concat('%', #{doctorName}, '%'))


        and department_id = #{departmentId}


        and work_date = str_to_date(#{workDate}, '%Y-%m-%d')


        and status = #{status}

select ds.schedule_id, ds.doctor_id, ds.department_id, ds.work_date, ds.max_number, ds.interval_minute, ds.status, ds.am_start_time, ds.am_end_time, ds.pm_start_time, ds.pm_end_time, de.real_name as doctorName, de.doctor_title, d.name as departmentName from doctor_schedule ds join doctor_exp de on ds.doctor_id = de.doctor_id join department d on ds.department_id = d.department_id
and de.real_name like concat('%', #{doctorName}, '%')
and ds.department_id = #{departmentId}
and ds.work_date = str_to_date(#{workDate}, '%Y-%m-%d')
and ds.status = #{status}
order by ds.work_date desc limit #{offset}, #{pageSize}

mapper.insert:
INSERT INTO doctor_schedule ( doctor_id, department_id, work_date, am_start_time, am_end_time, pm_start_time, pm_end_time, interval_minute, max_number, status, create_time )
SELECT #{item.doctorId}, d.department_id, #{item.workDate}, #{item.amStartTime}, #{item.amEndTime}, #{item.pmStartTime}, #{item.pmEndTime}, #{item.intervalMinute}, #{item.maxNumber}, 0, now()
FROM doctor_exp d WHERE d.doctor_id = #{item.doctorId}
